INSERT INTO `daily_report` VALUES (3,12,9,'2026-02-04','와, 목표 범위 비율(TIR) 91%라니 정말 대단해요! ? 최고 혈당 213과 최저 혈당 56으로 혈당이 크게 움직인 순간이 있었지만, 평균 혈당 119로 잘 관리해 주셨어요. 꾸준한 모습 정말 멋져요, 내일도 함께 힘내요! ❤️',91,'DAILY','2026-02-05 11:57:09','2026-02-05 11:57:09'),(4,12,9,'2026-02-05','오늘 목표 범위 비율(TIR) 80%를 달성하셨네요! 정말 잘하고 계세요. ? 다만 오므라이스 식사 후 최고 혈당이 228까지 오른 점은 한번 확인해볼까요? 다음엔 밥 양을 살짝 조절해보는 것도 좋은 방법이 될 거예요, 제가 늘 곁에서 응원할게요! ?',80,'DAILY','2026-02-06 05:00:13','2026-02-06 05:00:13'),(5,23,11,'2025-12-07','오늘 목표범위비율(TIR) 85%를 달성하셨네요! 정말 대단해요! ? 다만 최고 혈당이 240까지 오른 걸 보니, 카레라이스나 자장밥 같은 덮밥류 식사 후 혈당 변화에 조금 더 신경 써주시면 좋을 것 같아요. ? 그래도 평균 혈당 108로 잘 관리하고 계시니, 내일은 더 멋진 하루 만들어봐요! 파이팅! ?',85,'DAILY','2026-02-06 21:42:02','2026-02-06 21:42:01'),(6,23,11,'2025-12-08','와! 목표 범위 비율(TIR) 88%라니, 정말 안정적으로 관리하고 계시네요! ? 다만 최고 혈당이 256까지 오른 순간이 있었는데, 김치볶음밥이나 장어덮밥처럼 밥 위주 식사가 영향을 준 것 같아요. 그래도 평균 혈당 124로 정말 잘해주셨어요, 제가 늘 곁에서 응원할게요! ?',88,'DAILY','2026-02-06 21:42:42','2026-02-06 21:42:42'),(7,23,11,'2025-12-09','우와, 오늘 목표 범위 비율(TIR)이 93%라니 정말 대단해요! ? 다만 점심 식사 후 최고 혈당이 265까지 오른 점은 한번 살펴보면 좋을 것 같아요. ? 그래도 평균 혈당 111로 안정적이게 하루를 마무리하셨으니 너무 걱정 마세요! ?',93,'DAILY','2026-02-06 21:43:20','2026-02-06 21:43:20'),(8,23,11,'2025-12-10','오늘 하루도 혈당 관리하시느라 정말 고생 많으셨어요! 목표 범위 비율(TIR) 87%를 달성하신 건 정말 멋진 성과예요.? 다만 점심, 저녁에 드신 볶음밥의 영향으로 최고 혈당이 261까지 오른 것 같아요. ? 다음 식사에는 채소를 먼저 드시면 혈당을 완만하게 올리는 데 도움이 될 거예요! ?',87,'DAILY','2026-02-06 21:43:56','2026-02-06 21:43:56'),(9,23,11,'2025-12-11','와, 목표 범위 비율(TIR)이 85%라니! 정말 훌륭하게 관리하고 계시네요. ? 다만, 식사 후 최고 혈당이 277까지 오른 점은 한번 되돌아보면 좋을 것 같아요. 다음 식사 후에는 가볍게 10분 정도 걸어보시면 혈당 스파이크를 막는 데 큰 도움이 될 거예요! ?',85,'DAILY','2026-02-06 21:44:33','2026-02-06 21:44:33'),(10,23,11,'2025-12-12','오늘 하루도 정말 고생 많으셨어요! 목표 범위 비율(TIR) 82%라니, 정말 훌륭하게 관리하셨네요! ? 최고 혈당이 250까지 올랐던 순간이 있었는데, 아마 맛있는 밥 종류의 식사가 영향을 준 것 같아요. ? 그래도 평균 혈당 128로 잘 마무리하셨으니 너무 걱정 마세요, 내일도 제가 함께 뛸게요! ?',82,'DAILY','2026-02-06 21:45:00','2026-02-06 21:45:00'),(11,23,11,'2025-12-13','와, 평균 혈당 98에 목표 범위 비율(TIR) 83%라니! 정말 꾸준히 잘 관리하고 계시는군요! ? 다만 최고 혈당 220, 최저 혈당 53으로 혈당 변동이 조금 컸던 하루였어요. ? 짬뽕밥처럼 국물이 있는 식사는 건더기 위주로 드시면 혈당을 완만하게 올리는 데 도움이 될 거예요! ?',83,'DAILY','2026-02-06 21:45:27','2026-02-06 21:45:26'),(12,23,11,'2025-12-14','오늘 하루도 정말 고생 많으셨어요! 목표 범위 비율(TIR)이 79%나 되네요, 정말 잘하고 계세요. ? 다만 최고 혈당이 260까지 오른 점은 우리 함께 조금만 신경 써봐요. ? 다음 덮밥 식사 때는 밥 양을 살짝 조절하거나 채소를 더 곁들여보면 어떨까요? ?',79,'DAILY','2026-02-06 21:45:50','2026-02-06 21:45:49'),(13,23,11,'2025-12-15','오늘 하루도 혈당 관리하시느라 정말 고생 많으셨어요! 목표 범위 비율(TIR) 79% 달성, 정말 멋진데요? ? 다만 최고 혈당이 254까지 오른 점이 조금 마음에 걸리는데, 자장밥처럼 소스와 밥이 어우러진 식사는 혈당을 급격히 높일 수 있답니다. 그래도 꾸준히 기록하고 노력하는 모습이 정말 최고예요, 제가 늘 곁에서 응원할게요! ?',79,'DAILY','2026-02-06 21:46:18','2026-02-06 21:46:17'),(14,23,11,'2025-12-16','오늘 하루 목표 범위 비율(TIR) 84%를 달성하셨네요, 정말 잘하고 계세요! ? 다만, 최고 혈당이 269까지 오른 점을 고려할 때 볶음밥이나 장어덮밥 같은 덮밥류 식사 후 가벼운 산책을 추가하면 더욱 좋을 거예요. ?‍♀️ 꾸준히 노력하는 모습이 정말 멋져요, 내일도 함께 힘내요! ?',84,'DAILY','2026-02-06 21:46:33','2026-02-06 21:46:32'),(16,23,12,'2025-12-18','우와, 목표범위비율(TIR) 84%라니 정말 훌륭해요! 꾸준히 노력해주신 덕분이에요.? 다만, 최고 혈당이 268까지 올랐다가 최저 60까지 내려가서 혈당 변동이 조금 컸네요. 특히 밥과 면이 함께 있는 잡채밥 같은 식사는 혈당을 급격히 높일 수 있으니, 다음엔 채소를 먼저 드시면 큰 도움이 될 거예요!?',84,'DAILY','2026-02-06 21:52:02','2026-02-06 21:52:02'),(17,23,12,'2025-12-19','오늘 목표 범위(TIR) 78% 달성! 정말 잘하고 계세요! ? 다만, 최고 혈당이 267까지 오른 점은 조금 아쉬워요. 짬뽕밥, 장어덮밥처럼 밥 위주 식사는 혈당을 빠르게 올릴 수 있답니다. ? 내일은 식사 순서를 채소부터 드셔보는 건 어떨까요? 제가 옆에서 함께 응원할게요! ?',78,'DAILY','2026-02-06 21:52:29','2026-02-06 21:52:28'),(18,23,12,'2025-12-20','오늘 하루도 정말 애쓰셨어요! 목표 범위 비율(TIR)이 83%라니, 정말 꾸준히 잘 관리하고 계시네요. ? 다만, 식후 최고 혈당이 227까지 오른 점이 조금 아쉬워요. 다음 비빔밥 식사 때는 밥 양을 살짝 조절하거나 식후 가벼운 산책을 추가하면 훨씬 더 좋은 결과를 만들 수 있을 거예요! ?',83,'DAILY','2026-02-06 21:52:45','2026-02-06 21:52:45'),(19,23,12,'2025-12-21','우와! 목표 범위 비율(TIR)이 91%라니 정말 대단해요!? 다만 최고 혈당이 212까지 오른 것은 김치볶음밥의 영향일 수 있으니 다음엔 양을 살짝 조절해보는 건 어떨까요? 평균 혈당 114로 꾸준히 잘하고 계시니 오늘도 제가 곁에서 응원할게요! ?',91,'DAILY','2026-02-06 21:53:08','2026-02-06 21:53:08'),(20,23,12,'2025-12-22','와! 오늘 목표 범위 비율(TIR)이 84%나 되네요! 정말 멋진 하루였어요. ? 다만 최고 혈당이 235까지 오른 걸 보면, 덮밥처럼 탄수화물이 많은 식사는 혈당을 꽤 높일 수 있다는 신호일 수 있어요. 그래도 평균 혈당 112로 잘 마무리하셨으니 